define([
    'jquery',
    'mage/translate',
    'mage/cookies',
    'Magento_Ui/js/modal/alert'
], function ($, $t, _cookies, alertModal) {
    'use strict';

    function escapeHtml(value)
    {
        return String(value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    function showAlert(message)
    {
        alertModal({
            title: $t('B2B'),
            content: message
        });
    }

    function normalizeSku(sku)
    {
        return $.trim(sku || '').toLowerCase();
    }

    function getFormKey()
    {
        if (window.FORM_KEY) {
            return window.FORM_KEY;
        }

        if ($.mage && $.mage.cookies) {
            return $.mage.cookies.get('form_key') || '';
        }

        return '';
    }

    return function (config, element) {
        let messages = config.messages || {};
        let addUrl = config.addUrl || '';
        // Missão estabilização 2026-10-22 (P2): preview do produto por SKU.
        let lookupUrl = config.lookupUrl || (addUrl ? addUrl.replace(/\/add\/?$/, '/lookup') : '');
        let initialRows = parseInt(config.initialRows, 10) || 5;
        var skuAriaLabel = messages.skuAriaLabel || $t('Código SKU');
        var qtyAriaLabel = messages.qtyAriaLabel || $t('Quantidade');
        var removeAriaLabel = messages.removeRow || $t('Remover');
        var suggestionsAriaLabel = messages.suggestionsAriaLabel || $t('Sugestões de SKU');

        var $root = $(element);
        var $rowsContainer = $root.find('#quickorder-rows');
        var $results = $root.find('#quickorder-results');
        var $success = $root.find('#quickorder-success');
        var $errors = $root.find('#quickorder-errors');
        var $container = $root.find('#quickorder-container');
        var $submitButton = $root.find('#quickorder-submit');
        var $submitButtonText = $submitButton.find('span');

        // CSV elements
        var $csvZone = $root.find('#quickorder-csv-zone');
        var $dropzone = $root.find('#csv-dropzone');
        var $fileInput = $root.find('#csv-file-input');
        var $csvStatus = $root.find('#csv-status');
        var $csvDownloadSample = $root.find('#csv-download-sample');

        let rowIndex = 0;
        // M15: SKU Autocomplete configuration
        let searchUrl = config.searchUrl || '/catalogsearch/ajax/suggest';

        function initSkuAutocomplete($input)
        {
            var $row = $input.closest('.quickorder-row');
            var $suggestions = $row.find('.sku-suggestions');
            var highlightedIndex = -1;
            var suggestionId = $suggestions.attr('id');
            var autocompleteDelay = null;
            var activeRequest = null;
            var requestNonce = 0;

            function hideSuggestions()
            {
                requestNonce += 1;
                highlightedIndex = -1;
                if (activeRequest && activeRequest.readyState !== 4) {
                    activeRequest.abort();
                }
                activeRequest = null;
                $suggestions.hide().empty().attr('aria-hidden', 'true');
                $input.attr('aria-expanded', 'false');
            }

            function applySelection(skuValue)
            {
                $input.val(skuValue);
                hideSuggestions();
                $input.closest('.quickorder-row').find('.qty-input').focus();
            }

            function setHighlight(index)
            {
                var $items = $suggestions.find('.sku-suggestion');
                if (!$items.length) {
                    highlightedIndex = -1;
                    return;
                }

                highlightedIndex = Math.max(0, Math.min(index, $items.length - 1));
                $items.removeClass('is-highlighted').attr('aria-selected', 'false');
                $items.eq(highlightedIndex).addClass('is-highlighted').attr('aria-selected', 'true');
            }

            if (suggestionId) {
                $input.attr('aria-controls', suggestionId);
            }

            $input.on('input', function () {
                let query = $.trim($(this).val());
                var currentNonce;
                clearTimeout(autocompleteDelay);
                highlightedIndex = -1;

                requestNonce += 1;
                currentNonce = requestNonce;

                if (activeRequest && activeRequest.readyState !== 4) {
                    activeRequest.abort();
                }

                if (query.length < 3) {
                    hideSuggestions();
                    return;
                }

                autocompleteDelay = setTimeout(function () {
                    activeRequest = $.ajax({
                        url: searchUrl,
                        data: { q: query },
                        type: 'GET',
                        dataType: 'json'
                    }).done(function (data) {
                        if (currentNonce !== requestNonce) {
                            return;
                        }

                        $suggestions.empty();
                        let items = data || [];
                        if (items.length === 0) {
                            hideSuggestions();
                            return;
                        }

                        $.each(items.slice(0, 8), function (_, item) {
                            let title = escapeHtml(item.title || item.name || '');
                            let sku = escapeHtml(item.sku || item.title || '');
                            let optionId = suggestionId + '-option-' + _;
                            $suggestions.append(
                                '<button type="button" id="' + optionId + '" class="sku-suggestion" role="option" aria-selected="false" data-sku="' + sku + '">' +
                                '<span class="sku-suggestion-sku">' + sku + '</span>' +
                                '<span class="sku-suggestion-name">' + title + '</span>' +
                                '</button>'
                            );
                        });
                        $suggestions.show().attr('aria-hidden', 'false');
                        $input.attr('aria-expanded', 'true');
                    }).fail(function (_jqXHR, textStatus) {
                        if (textStatus !== 'abort') {
                            hideSuggestions();
                        }
                    }).always(function () {
                        activeRequest = null;
                    });
                }, 300);
            });

            $input.on('blur', function () {
                setTimeout(function () {
                    var activeElement = document.activeElement;
                    if (activeElement && $suggestions[0] && $suggestions[0].contains(activeElement)) {
                        return;
                    }
                    hideSuggestions();
                }, 200);
            });

            $suggestions.on('focusout', function () {
                setTimeout(function () {
                    var activeElement = document.activeElement;
                    if (activeElement === $input[0]) {
                        return;
                    }

                    if ($suggestions[0] && activeElement && $suggestions[0].contains(activeElement)) {
                        return;
                    }

                    hideSuggestions();
                }, 0);
            });

            $input.on('keydown', function (event) {
                var $items = $suggestions.find('.sku-suggestion');

                if (!$items.length || !$suggestions.is(':visible')) {
                    return;
                }

                if (event.key === 'ArrowDown') {
                    event.preventDefault();
                    setHighlight(highlightedIndex + 1);
                    return;
                }

                if (event.key === 'ArrowUp') {
                    event.preventDefault();
                    setHighlight(highlightedIndex <= 0 ? $items.length - 1 : highlightedIndex - 1);
                    return;
                }

                if (event.key === 'Enter' && highlightedIndex >= 0) {
                    event.preventDefault();
                    applySelection($items.eq(highlightedIndex).data('sku'));
                    return;
                }

                if (event.key === 'Escape') {
                    event.preventDefault();
                    hideSuggestions();
                }
            });

            $suggestions.on('click', '.sku-suggestion', function () {
                applySelection($(this).data('sku'));
            });
        }

        function buttonText(text)
        {
            if ($submitButtonText.length) {
                $submitButtonText.text(text);
                return;
            }

            $submitButton.text(text);
        }

        /**
         * Missão estabilização 2026-10-22 (P2): consulta o produto por SKU e
         * apresenta nome, imagem, preço autorizado, disponibilidade e regras de
         * quantidade na própria linha, antes da inclusão. Nunca adiciona sozinho.
         */
        function initSkuLookup($input)
        {
            if (!lookupUrl) {
                return;
            }

            var $row = $input.closest('.quickorder-row');
            var $detail = $row.find('.sku-detail');
            var delay = null;
            var nonce = 0;

            if (!$detail.length) {
                $detail = $('<div class="sku-detail" role="status" aria-live="polite" hidden></div>');
                $row.append($detail);
            }

            function clearDetail()
            {
                nonce += 1;
                if (delay) {
                    clearTimeout(delay);
                    delay = null;
                }
                $detail.empty().attr('hidden', 'hidden');
            }

            function renderNotFound()
            {
                $detail
                    .attr('class', 'sku-detail sku-detail--error')
                    .removeAttr('hidden')
                    .html('<span class="sku-detail__status">' + escapeHtml($t('SKU não encontrado ou sem preço autorizado para a sua conta.')) + '</span>');
            }

            function renderItem(item)
            {
                var html = '';
                var availability = (item.availability && item.availability.label)
                    ? item.availability.label : '';
                var priceHtml = (item.price && item.price.html) ? item.price.html : '';
                var qtyRules = [];
                var q = item.qty || {};

                if (q.min) { qtyRules.push($t('Mínimo %1').replace('%1', q.min)); }
                if (q.step && q.step > 1) { qtyRules.push($t('Múltiplo de %1').replace('%1', q.step)); }

                html += '<div class="sku-detail__media">';
                if (item.image) {
                    html += '<img src="' + escapeHtml(item.image) + '" alt="" width="48" height="48" loading="lazy">';
                }
                html += '</div>';
                html += '<div class="sku-detail__info">';
                html += '<span class="sku-detail__name">' + escapeHtml(item.name || item.sku || '') + '</span>';
                if (priceHtml) {
                    html += '<span class="sku-detail__price">' + priceHtml + '</span>';
                }
                if (availability) {
                    html += '<span class="sku-detail__stock">' + escapeHtml(availability) + '</span>';
                }
                if (qtyRules.length) {
                    html += '<span class="sku-detail__rules">' + escapeHtml(qtyRules.join(' · ')) + '</span>';
                }
                if (item.requires_config) {
                    html += '<span class="sku-detail__config">' + escapeHtml($t('Este produto exige a escolha de opções. Abra a página do produto para configurar.')) + '</span>';
                }
                if (item.addable === false) {
                    html += '<span class="sku-detail__blocked">' + escapeHtml($t('Este item não está disponível para compra na sua conta.')) + '</span>';
                }
                html += '</div>';

                $detail
                    .attr('class', 'sku-detail sku-detail--ok')
                    .removeAttr('hidden')
                    .html(html);
            }

            function lookup(sku)
            {
                var currentNonce;
                var query = $.trim(sku || '');

                if (query.length < 3) {
                    clearDetail();
                    return;
                }

                nonce += 1;
                currentNonce = nonce;

                $detail
                    .attr('class', 'sku-detail sku-detail--loading')
                    .removeAttr('hidden')
                    .html('<span class="sku-detail__status">' + escapeHtml($t('Consultando produto…')) + '</span>');

                $.ajax({
                    url: lookupUrl,
                    data: { q: query },
                    type: 'GET',
                    dataType: 'json'
                }).done(function (data) {
                    if (currentNonce !== nonce) {
                        return;
                    }

                    if (data && data.success && data.found && data.item) {
                        renderItem(data.item);
                        return;
                    }

                    renderNotFound();
                }).fail(function (_jqXHR, textStatus) {
                    if (textStatus === 'abort' || currentNonce !== nonce) {
                        return;
                    }
                    renderNotFound();
                });
            }

            $input.on('input', function () {
                var value = $.trim($(this).val());

                if (delay) {
                    clearTimeout(delay);
                }

                if (value.length < 3) {
                    clearDetail();
                    return;
                }

                delay = setTimeout(function () {
                    lookup(value);
                }, 450);
            });

            $input.on('blur', function () {
                var value = $.trim($(this).val());
                if (value.length >= 3) {
                    if (delay) {
                        clearTimeout(delay);
                    }
                    lookup(value);
                }
            });

            $input.on('keydown', function (event) {
                if (event.key === 'Enter') {
                    var value = $.trim($(this).val());
                    if (value.length >= 3) {
                        event.preventDefault();
                        if (delay) {
                            clearTimeout(delay);
                        }
                        lookup(value);
                    }
                }
            });
        }

        function createRow()
        {
            rowIndex += 1;

            return [
                '<div class="quickorder-row" data-index="', rowIndex, '">',
                '<input type="text" name="items[', rowIndex, '][sku]"',
                ' placeholder="', escapeHtml(messages.skuPlaceholder || 'Ex: SKU-001'), '" class="sku-input"',
                ' autocomplete="off" autocapitalize="off" spellcheck="false"',
                ' aria-label="', escapeHtml(skuAriaLabel), '" aria-expanded="false" />',
                '<div id="sku-suggestions-', rowIndex, '" class="sku-suggestions" role="listbox"',
                ' aria-label="', escapeHtml(suggestionsAriaLabel), '" aria-hidden="true"></div>',
                '<input type="number" name="items[', rowIndex, '][qty]" value="1" min="1" class="qty-input"',
                ' aria-label="', escapeHtml(qtyAriaLabel), '" />',
                '<button type="button" class="btn-remove" title="', escapeHtml(removeAriaLabel), '" aria-label="',
                escapeHtml(removeAriaLabel), '">&times;</button>',
                '</div>'
            ].join('');
        }

        function addRow()
        {
            let html = createRow();
            $rowsContainer.append(html);
            var $lastRow = $rowsContainer.find('.quickorder-row:last');
            initSkuAutocomplete($lastRow.find('.sku-input'));
            initSkuLookup($lastRow.find('.sku-input'));
        }

        function clearStatuses()
        {
            $rowsContainer.find('.quickorder-row').removeClass('has-error');
        }

        function setResultsVisible(isVisible)
        {
            $results
                .toggleClass('is-hidden', !isVisible)
                .prop('hidden', !isVisible)
                .attr('aria-hidden', isVisible ? 'false' : 'true');
        }

        /**
         * Parse CSV text into array of {sku, qty} objects
         * Supports: SKU,QTY and SKU;QTY formats
         * First line is skipped if it looks like a header
         */
        function parseCSV(text)
        {
            let lines = text.split(/\r?\n/);
            let items = [];
            let separator = ',';

            // Detect separator from first non-empty line
            for (let s = 0; s < lines.length; s++) {
                let trimmed = $.trim(lines[s]);
                if (trimmed) {
                    if (trimmed.indexOf(';') > -1 && trimmed.indexOf(',') === -1) {
                        separator = ';';
                    }
                    break;
                }
            }

            $.each(lines, function (index, line) {
                line = $.trim(line);
                if (!line) {
                    return;
                }

                let parts = line.split(separator);
                let sku = $.trim(parts[0] || '').replace(/^["']|["']$/g, '');
                let qtyStr = $.trim(parts[1] || '').replace(/^["']|["']$/g, '');

                // Skip header row
                if (index === 0 && sku && isNaN(parseInt(qtyStr, 10)) &&
                    /^(sku|codigo|código|produto|product|item)/i.test(sku)) {
                    return;
                }

                if (!sku) {
                    return;
                }

                let qty = parseInt(qtyStr, 10);
                if (isNaN(qty) || qty < 1) {
                    qty = 1;
                }

                items.push({ sku: sku, qty: qty });
            });

            return items;
        }

        /**
         * Clear existing rows and populate from parsed CSV items
         */
        function populateFromCSV(items)
        {
            // Remove all existing rows
            $rowsContainer.find('.quickorder-row').remove();
            rowIndex = 0;

            if (!items.length) {
                showAlert(messages.csvEmpty || $t('O arquivo CSV não contém produtos válidos.'));
                for (let i = 0; i < initialRows; i++) {
                    addRow();
                }
                return;
            }

            // Create rows for each CSV item
            $.each(items, function (idx, item) {
                addRow();
                var $row = $rowsContainer.find('.quickorder-row').last();
                $row.find('.sku-input').val(item.sku);
                $row.find('.qty-input').val(item.qty);
            });

            // Add a few extra empty rows
            addRow();
            addRow();

            let msg = (messages.csvLoaded || $t('%1 produto(s) carregado(s) do CSV.'))
                .replace('%1', items.length);
            $csvStatus.text(msg).addClass('csv-status--success').show();

            setTimeout(function () {
                $csvStatus.removeClass('csv-status--success').fadeOut();
            }, 5000);
        }

        /**
         * Handle file from input or drag-drop
         */
        function handleCSVFile(file)
        {
            if (!file) {
                return;
            }

            // Validate file type
            let name = (file.name || '').toLowerCase();
            if (name.indexOf('.csv') === -1 && file.type.indexOf('csv') === -1 && file.type !== 'text/plain') {
                showAlert(messages.csvInvalidFile || $t('Selecione um arquivo .csv válido.'));
                return;
            }

            let reader = new FileReader();
            reader.onload = function (e) {
                let text = e.target.result;
                let items = parseCSV(text);
                populateFromCSV(items);
            };
            reader.onerror = function () {
                showAlert(messages.csvInvalidFile || $t('Erro ao ler o arquivo.'));
            };
            reader.readAsText(file, 'UTF-8');
        }

        /**
         * Generate and download a sample CSV file
         */
        function downloadSampleCSV()
        {
            let csvContent = 'SKU,Quantidade\n';
            csvContent += 'BAG-CG160-001,2\n';
            csvContent += 'RET-TITAN-003,1\n';
            csvContent += 'BAU-45L-PRETO,3\n';

            let blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            let url = URL.createObjectURL(blob);
            let link = document.createElement('a');
            link.setAttribute('href', url);
            link.setAttribute('download', 'modelo-pedido-rapido.csv');
            link.style.display = 'none';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);
        }

        function renderSuccessList(added, message)
        {
            if (!added || !added.length) {
                $success.empty().hide();
                return;
            }

            let html = '<strong>' + escapeHtml(message || '') + '</strong><ul>';

            $.each(added, function (index, item) {
                html += '<li>' + escapeHtml(item.name || '') +
                    ' (SKU: ' + escapeHtml(item.sku || '') + ') - Qtd: ' + escapeHtml(item.qty || 0) + '</li>';
            });

            html += '</ul>';
            $success.html(html).show();
        }

        function renderErrorList(errorList)
        {
            if (!errorList || !errorList.length) {
                $errors.empty().hide();
                return;
            }

            let html = '<strong>' + escapeHtml($t('Erros:')) + '</strong><ul>';
            $.each(errorList, function (index, item) {
                html += '<li>SKU: ' + escapeHtml(item.sku || '') + ' - ' + escapeHtml(item.message || '') + '</li>';
            });
            html += '</ul>';
            $errors.html(html).show();
        }

        function collectItems()
        {
            let aggregated = {};
            let rowMap = {};

            $rowsContainer.find('.quickorder-row').each(function () {
                var $row = $(this);
                let sku = $.trim($row.find('.sku-input').val());
                let qty = parseInt($row.find('.qty-input').val(), 10) || 1;
                let key;

                if (!sku) {
                    return;
                }

                qty = Math.max(1, qty);
                key = normalizeSku(sku);

                if (!aggregated[key]) {
                    aggregated[key] = {
                        sku: sku,
                        qty: 0
                    };
                    rowMap[key] = [];
                }

                aggregated[key].qty += qty;
                rowMap[key].push($row);
            });

            return {
                items: $.map(aggregated, function (item) {
                    return item;
                }),
            rowMap: rowMap
            };
        }

        function markErrorRows(errorsList, rowMap)
        {
            $.each(errorsList || [], function (index, item) {
                let key = normalizeSku(item.sku || '');
                let rows = rowMap[key] || [];

                $.each(rows, function (_, $row) {
                    $row.addClass('has-error');
                });
            });
        }

        function submitQuickOrder()
        {
            if (!addUrl) {
                return;
            }

            clearStatuses();
            setResultsVisible(false);
            $success.empty();
            $errors.empty();

            let payload = collectItems();
            if (!payload.items.length) {
                showAlert(messages.skuRequired || $t('Informe pelo menos um SKU.'));
                return;
            }

            $submitButton.prop('disabled', true);
            buttonText(messages.processing || $t('Processando...'));
            $container.addClass('quickorder-loading');

            $.ajax({
                url: addUrl,
                type: 'POST',
                dataType: 'json',
                data: {
                    items: payload.items,
                    form_key: getFormKey()
                }
            }).done(function (response) {
                var added = Array.isArray(response && response.added) ? response.added : [];
                var errors = Array.isArray(response && response.errors) ? response.errors : [];
                var hasRenderableResults = added.length > 0 || errors.length > 0;
                var hasSuccessFlag = !!(response && response.success);

                renderSuccessList(added, (response && response.message) || '');
                renderErrorList(errors);
                markErrorRows(errors, payload.rowMap);
                setResultsVisible(hasRenderableResults);

                if (!hasSuccessFlag && errors.length === 0) {
                    showAlert((response && response.message) || (messages.requestError || $t('Erro ao processar pedido. Tente novamente.')));
                }
            }).fail(function () {
                showAlert(messages.requestError || $t('Erro ao processar pedido. Tente novamente.'));
            }).always(function () {
                $submitButton.prop('disabled', false);
                buttonText(messages.addToCart || $t('Adicionar ao Carrinho'));
                $container.removeClass('quickorder-loading');
            });
        }

        $root.on('click', '#quickorder-add-row', function () {
            addRow();
        });

        $rowsContainer.on('click', '.btn-remove', function () {
            var $allRows = $rowsContainer.find('.quickorder-row');
            if ($allRows.length <= 1) {
                return;
            }

            $(this).closest('.quickorder-row').remove();
        });

        $root.on('click', '#quickorder-submit', function () {
            submitQuickOrder();
        });

        // === CSV Upload: Drag & Drop ===
        $dropzone.on('dragover dragenter', function (e) {
            e.preventDefault();
            e.stopPropagation();
            $(this).addClass('csv-dropzone--active');
        });

        $dropzone.on('dragleave drop', function (e) {
            e.preventDefault();
            e.stopPropagation();
            $(this).removeClass('csv-dropzone--active');
        });

        $dropzone.on('drop', function (e) {
            let files = e.originalEvent.dataTransfer && e.originalEvent.dataTransfer.files;
            if (files && files.length) {
                handleCSVFile(files[0]);
            }
        });

        // Click on dropzone opens file dialog
        $dropzone.on('click', function () {
            $fileInput.trigger('click');
        });

        // Keyboard accessibility: Enter/Space opens file dialog
        $dropzone.on('keydown', function (e) {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                $fileInput.trigger('click');
            }
        });

        // File input change
        $fileInput.on('change', function () {
            let files = this.files;
            if (files && files.length) {
                handleCSVFile(files[0]);
                // Reset input so same file can be re-uploaded
                $(this).val('');
            }
        });

        // Download sample CSV
        $csvDownloadSample.on('click', function (e) {
            e.preventDefault();
            downloadSampleCSV();
        });

        for (let i = 0; i < initialRows; i += 1) {
            addRow();
        }
    };
});
